CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,url TEXT NOT NULL,note TEXT NOT NULL,last_success TEXT,last_attempt TEXT);
CREATE TABLE IF NOT EXISTS stores(id TEXT PRIMARY KEY,chain TEXT NOT NULL REFERENCES sources(id),name TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,cap TEXT NOT NULL,source_url TEXT NOT NULL,verified_at TEXT NOT NULL,favorite INTEGER NOT NULL DEFAULT 0,loyalty INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, chain TEXT NOT NULL REFERENCES sources(id),store_id TEXT REFERENCES stores(id), title TEXT NOT NULL,category TEXT NOT NULL,variant TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents>0),unit TEXT NOT NULL,pack_size REAL NOT NULL CHECK(pack_size>0),loose INTEGER NOT NULL DEFAULT 0,min_packs INTEGER NOT NULL DEFAULT 1,loyalty INTEGER NOT NULL DEFAULT 0,conditions TEXT NOT NULL DEFAULT '',conditions_known INTEGER NOT NULL DEFAULT 1,valid_from TEXT NOT NULL,valid_to TEXT NOT NULL,url TEXT NOT NULL,origin TEXT NOT NULL,scope TEXT NOT NULL,fetched_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS offers_dates ON offers(valid_from,valid_to,chain);
CREATE TABLE IF NOT EXISTS list_items(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,variant TEXT NOT NULL DEFAULT '',quantity REAL NOT NULL CHECK(quantity>0),unit TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,chain TEXT,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL);
PRAGMA user_version=1;
